#ifndef INSTRUCTION_HPP
#define INSTRUCTION_HPP

#include <utility>
#include "Common.h"
#include <string>
#include <iostream>

using Instruction = unsigned int;

class InstructionBase {
public:
    unsigned opcode, rs1, rs2, rd, funct3, funct7;
    Immediate imm;
    Instruction inst;
    enum Type t;

    InstructionBase() : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(0), t(static_cast<Type>(0)) {}

    explicit InstructionBase(unsigned) : opcode(0b0010011), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(-1), t(I) {}

    static InstructionBase nop() {
        return InstructionBase();
    }

    static constexpr unsigned int bin_mask(int digits) {
        return (1 << digits) - 1;
    }

    static unsigned int get_digits(unsigned int n, int hi, int lo) {
        return (n >> lo) & bin_mask(hi - lo + 1);
    }

    static unsigned int expand_digit(unsigned int digit, int lo) {
        return digit << lo;
    }

    bool is_nop() const {
        return inst == 0;
    }

    bool is_valid(const std::string &key) const {
        // Placeholder for validation logic
        return true;
    }

    void verify(const std::string &key) const {
        if (!is_valid(key)) {
            throw InvalidAccess();
        }
    }

    void debug() const {
        std::cout << "Instruction: " << inst << std::endl;
    }

    bool has_op1() const {
        // Placeholder for operand check logic
        return true;
    }

    bool has_op2() const {
        // Placeholder for operand check logic
        return true;
    }

class InvalidAccess {};
};

class InstructionR : public InstructionBase {
public:
    explicit InstructionR(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 11, 7);
        rs2 = get_digits(inst, 16, 12);
        funct3 = get_digits(inst, 19, 17);
        rd = get_digits(inst, 24, 20);
        funct7 = get_digits(inst, 31, 25);
        t = R;
    }
};

class InstructionI : public InstructionBase {
public:
    explicit InstructionI(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 19, 17);
        rd = get_digits(inst, 24, 20);
        imm = Immediate(get_digits(inst, 31, 20));
        t = I;
    }
};

class InstructionS : public InstructionBase {
public:
    explicit InstructionS(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 11, 7);
        rs2 = get_digits(inst, 16, 12);
        funct3 = get_digits(inst, 19, 17);
        imm = Immediate((get_digits(inst, 31, 25) << 5) | get_digits(inst, 11, 7));
        t = S;
    }
};

class InstructionB : public InstructionBase {
public:
    explicit InstructionB(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rs1 = get_digits(inst, 11, 7);
        rs2 = get_digits(inst, 16, 12);
        funct3 = get_digits(inst, 19, 17);
        imm = Immediate((get_digits(inst, 31, 31) << 12) | (get_digits(inst, 7, 7) << 11) |
                          (get_digits(inst, 12, 8) << 1) | (get_digits(inst, 6, 5) << 5));
        t = B;
    }
};

class InstructionU : public InstructionBase {
public:
    explicit InstructionU(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 24, 20);
        imm = Immediate(get_digits(inst, 31, 12) << 12);
        t = U;
    }
};

class InstructionJ : public InstructionBase {
public:
    explicit InstructionJ(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 24, 20);
        imm = Immediate((get_digits(inst, 31, 31) << 20) | (get_digits(inst, 19, 12) << 12) |
                          (get_digits(inst, 20, 20) << 11) | (get_digits(inst, 30, 25) << 5));
        t = J;
    }
};

#endif // INSTRUCTION_HPP
